using System.Collections.Immutable;

namespace ConfigurationSourceGen.Validations;

public sealed class RegexValidator : IGenerateValidator {

    public string AttributeName { get; } = "RegularExpressionAttribute";

    public string GenerateAttributeSource(string ns) => $$"""
        // <auto-generated/>
        namespace {{ns}};

        [global::System.AttributeUsage(global::System.AttributeTargets.Property, AllowMultiple = false, Inherited = true)]
        public sealed class RegularExpressionAttribute : global::System.Attribute {
            public string Pattern { get; }

            public RegularExpressionAttribute(string pattern) {
                Pattern = pattern;
            }
        }
        """;

    public void Generate(CodeBuilder builder, ToGenerateProperty property, AttributeDefinition attribute, string valueExpression) {

        if (attribute.Arguments.Count == 0) {
            return;
        }

        string pattern = attribute.Arguments[0];

        builder.If($"!global::System.Text.RegularExpressions.Regex.IsMatch({valueExpression}, {pattern})", () => {
            ValidationGeneratorHelper.AddError(
                builder,
                property.Name,
                $"does not match the required format '{pattern}'.");
        });
    }
}